# OpenBCI Integration
import serial
import numpy as np

class OpenBCIReader:
    def __init__(self, port='/dev/ttyUSB0'):
        self.serial = serial.Serial(port, 115200)

    def read_data(self):
        # Read raw EEG data
        while True:
            line = self.serial.readline()
            # Parse and process data
            print(f"EEG data: {line}")
